import { Link, useNavigate } from "react-router-dom";
import { useEffect, useState } from "react";

function Navbar() {
  const [isLoggedIn, setIsLoggedIn] = useState(
    !!localStorage.getItem("userId")
  );
  const navigate = useNavigate();

  // Whenever localStorage changes (e.g., login/logout), re-check login status
  useEffect(() => {
    const handleStorageChange = () => {
      setIsLoggedIn(!!localStorage.getItem("userId"));
    };

    window.addEventListener("storage", handleStorageChange);

    return () => {
      window.removeEventListener("storage", handleStorageChange);
    };
  }, []);

  // Also check on component mount (in case of refresh)
  useEffect(() => {
    setIsLoggedIn(!!localStorage.getItem("userId"));
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("userId");
    localStorage.removeItem("full_name");
    setIsLoggedIn(false);
    navigate("/login"); // better than window.location.href
  };

  const userId = localStorage.getItem("userId");

  return (
    <nav className="bg-black bg-opacity-80 flex justify-end items-center h-12 px-8 shadow-lg">
      <Link
        to="/"
        className="text-white mx-4 text-lg uppercase hover:text-blue-400"
      >
        Back to First Page
      </Link>

      {isLoggedIn ? (
        <>
          <Link
            to="/homes"
            className="text-white mx-4 text-lg uppercase hover:text-blue-400"
          >
            Homes
          </Link>
          <Link
            to="/upload"
            className="text-white mx-4 text-lg uppercase hover:text-blue-400"
          >
            Upload
          </Link>
          <Link
            to={`/dashboard/${userId}`}
            className="text-white mx-4 text-lg uppercase hover:text-blue-400"
          >
            Dashboard
          </Link>
          <button
            onClick={handleLogout}
            className="text-white mx-4 text-lg uppercase hover:text-blue-400"
          >
            Logout
          </button>
        </>
      ) : (
        <>
          <Link
            to="/login"
            className="text-white mx-4 text-lg uppercase hover:text-blue-400"
          >
            Login
          </Link>
          <Link
            to="/signup"
            className="text-white mx-4 text-lg uppercase hover:text-blue-400"
          >
            Signup
          </Link>
        </>
      )}
    </nav>
  );
}

export default Navbar;
